-- Run with: lua tests/trade_tables.lua
-- trade_tables.lua is generated by tools/extract_trades/extract.lua; this checks its shape
-- and, where VoxeLibre is installed, that it is up to date.
local tables = dofile("trade_tables.lua")
assert(tables.version and tables.professions)
local count = 0
for name, profession in pairs(tables.professions) do
	for _, trade in ipairs(profession.trades) do
		assert(trade.tier >= 1 and trade.tier <= 5, name)
		assert(#trade.wanted >= 1 and #trade.offered == 1, name)
		for _, s in ipairs(trade.wanted) do assert(type(s.item) == "string" and s.min <= s.max, name) end
		count = count + 1
	end
end
assert(count > 250, "trades: " .. count)
local first = tables.professions.farmer.trades[1]
assert(first.wanted[1].item == "mcl_farming:wheat_item" and first.wanted[1].min == 20 and first.offered[1].item == "mcl_core:emerald")
assert(next(tables.professions.nitwit.trades) == nil and tables.professions.farmer.jobsite == "mcl_composters:composter")

local home = os.getenv("HOME")
local source = home and home .. "/.minetest/games/mineclone2/mods/ENTITIES/mobs_mc/villager.lua"
local handle = source and io.open(source, "r")
if handle then
	handle:close()
	local pipe = io.popen("luajit tools/extract_trades/extract.lua '" .. source .. "' " .. tables.version .. " 2>&1")
	local fresh = pipe:read("*a")
	pipe:close()
	local file = io.open("trade_tables.lua", "r")
	local current = file:read("*a")
	file:close()
	assert(fresh == current, "trade_tables.lua is out of date with the installed VoxeLibre: rerun tools/extract_trades/extract.lua")
end
print("trade_tables.lua: ok")
